from agents import function_tool
from kubernetes import client, config

config.load_kube_config()
_apps = client.AppsV1Api()


def _build_selector_patch(target_pool):
    return {"spec": {"template": {"spec": {"nodeSelector": {"node-pool": target_pool}}}}}


@function_tool
def move_pod_to_node_pool(deployment_name: str, namespace: str, target_pool: str) -> str:
    patch = _build_selector_patch(target_pool)
    _apps.patch_namespaced_deployment(name=deployment_name, namespace=namespace, body=patch)
    return f"Deployment {namespace}/{deployment_name} now targets node pool {target_pool}"

from kubernetes import client, config
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("k8s-cleanup")
config.load_kube_config()
batch_api = client.BatchV1Api()


@mcp.tool()
def delete_completed_jobs(namespace: str, name_prefix: str = "") -> str:
    if not namespace or not namespace.strip():
        return "Error: namespace is required"
    if namespace in ("kube-system", "kube-public", "kube-node-lease"):
        return f"Error: refusing to clean system namespace {namespace}"
    if name_prefix is None:
        name_prefix = ""
    jobs = batch_api.list_namespaced_job(namespace=namespace).items
    if not jobs:
        return f"No jobs found in {namespace}"
    deleted = []
    for job in jobs:
        if not name_prefix or job.metadata.name.startswith(name_prefix):
            if job.status.succeeded and job.status.succeeded > 0:
                batch_api.delete_namespaced_job(
                    name=job.metadata.name,
                    namespace=namespace,
                    propagation_policy="Background",
                )
                deleted.append(job.metadata.name)
    if not deleted:
        return "No matching completed jobs"
    return f"Deleted {len(deleted)} jobs: {', '.join(deleted)}"
